def compute(vars):
    net_capital = vars["v1"]
    excess_over_minimum = vars["v2"]
    minimum_requirement_billion = net_capital - excess_over_minimum
    minimum_requirement_million = minimum_requirement_billion * 1000

    return {
        "value": minimum_requirement_million,
        "trace": {
            "net_capital_billion": net_capital,
            "excess_over_minimum_billion": excess_over_minimum,
            "minimum_requirement_billion": minimum_requirement_billion,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": None
            }
        }
    }
